void UpdateWorld(){uintptr_t hero=GetHero();if(g_CombatActive&&CanRead(hero,0x90)){if(hero!=g_PrevHeroPtr){g_PrevHeroPtr=hero;g_PrevHeroHp=-1.f;}uintptr_t dam=*(uintptr_t*)(hero+0x68);if(g_EnemyDmg>1.01f&&CanWrite(dam,0x260)){for(int off=0x180;off<=0x230;off+=4){float cur=*(float*)(dam+off),mn=*(float*)(dam+off+4),mx=*(float*)(dam+off+8);if(mn==0.f&&mx>=100.f&&mx<=1000.f&&cur>0.f&&cur<=mx){if(g_PrevHeroHp>0.f&&g_PrevHeroHp-cur>=0.5f&&g_PrevHeroHp-cur<250.f){float adj=fmaxf(0.f,g_PrevHeroHp-(g_PrevHeroHp-cur)*g_EnemyDmg);*(float*)(dam+off)=adj;cur=adj;}g_PrevHeroHp=cur;break;}}}uintptr_t phys=*(uintptr_t*)(hero+0x6C);if(g_SpideySpeed>1.01f&&CanRead(phys,0x180)){uint32_t pf=*(uint32_t*)(phys+0x0C);if(pf&0x80000){uintptr_t bp=*(uintptr_t*)(phys+0x178);if(CanRead(bp,0x10)){uintptr_t* rbs=*(uintptr_t**)(bp+0x08);if(CanRead((uintptr_t)rbs,40)){for(int i=0;i<10;++i){uintptr_t rb=*(rbs+i);if(CanWrite(rb,0xE0)){float vx=*(float*)(rb+0xD0),vz=*(float*)(rb+0xD8);float v2=vx*vx+vz*vz;if(v2>2.f&&v2<2500.f){float b=1.f+(g_SpideySpeed-1.f)*0.035f;*(float*)(rb+0xD0)=vx*b;*(float*)(rb+0xD8)=vz*b;}}}}}}}}if(!CanRead(g_StormActor,0x80)||*(uint32_t*)(g_StormActor+0x10)!=0x96478E0A){g_StormActor=FindStormByHash();g_HasStormPrev=false;}if(CanRead(g_StormActor,0x80)){uintptr_t sph=*(uintptr_t*)(g_StormActor+0x6C);if(CanWrite(sph,0x50)){float vx=*(float*)(sph+0x20),vy=*(float*)(sph+0x24),vz=*(float*)(sph+0x28);float spd=sqrtf(vx*vx+vy*vy+vz*vz);if(g_TorchBoost&&g_TorchSpeed>1.01f&&spd>2.f){float cap=35.f+fminf(g_TorchSpeed-1.f,4.f)*12.f;if(spd<cap){float b=fminf(cap/spd,1.f+(g_TorchSpeed-1.f)*0.03f);vx*=b;vy*=b;vz*=b;*(float*)(sph+0x20)=vx;*(float*)(sph+0x24)=vy;*(float*)(sph+0x28)=vz;spd=sqrtf(vx*vx+vy*vy+vz*vz);}}g_StormVecSpd=spd;}uintptr_t po=*(uintptr_t*)(g_StormActor+0x14);if(CanRead(po,0x40)){float x=*(float*)(po+0x30),y=*(float*)(po+0x34),z=*(float*)(po+0x38);if(g_HasStormPrev){float dx=x-g_PrevStormX,dy=y-g_PrevStormY,dz=z-g_PrevStormZ;g_StormRealSpd=sqrtf(dx*dx+dy*dy+dz*dz)*60.f;}g_PrevStormX=x;g_PrevStormY=y;g_PrevStormZ=z;g_HasStormPrev=true;DWORD now=GetTickCount();if(now-g_LastLogMs>800){g_LastLogMs=now;char* dp=(char*)malloc(260);GetEnvironmentVariableA("USERPROFILE",dp,200);strcat(dp,"\\Desktop\\STORM_TELEMETRY_AUTO.txt");FILE* f=fopen(dp,"a");if(f){fprintf(f,"boost=%d mul=%.2f real_spd=%.2f vec_spd=%.2f pos=(%.1f,%.1f,%.1f)\n",(int)g_TorchBoost,g_TorchSpeed,g_StormRealSpd,g_StormVecSpd,x,y,z);if(!g_DumpedMem&&g_StormRealSpd>2.f){g_DumpedMem=true;uintptr_t ai=*(uintptr_t*)(g_StormActor+0x7C);fprintf(f,"DUMP act=0x%08X ph=0x%08X ai=0x%08X\n",(uint32_t)g_StormActor,(uint32_t)sph,(uint32_t)ai);if(CanRead(sph,0x190)){for(int o=0;o<0x190;o+=4){float v=*(float*)(sph+o);if(v>1.f&&v<500.f)fprintf(f,"  PH+0x%03X = %.3f\n",o,v);}}if(CanRead(ai,0x120)){for(int o=0;o<0x120;o+=4){float v=*(float*)(ai+o);if(v>1.f&&v<500.f)fprintf(f,"  AI+0x%03X = %.3f\n",o,v);}}}fclose(f);}free(dp);}}}else{g_HasStormPrev=false;g_StormRealSpd=0;g_StormVecSpd=0;}}
